# Python: Calculate succession velocity with skill gap weighting
import numpy as np
import pandas as pd

def calculate_succession_velocity(candidate_skills, role_requirements, learning_rates):
    """
    Estimate months to readiness based on skill gaps and learning velocity.

    candidate_skills: dict of {skill_id: proficiency_level (1-5)}
    role_requirements: dict of {skill_id: required_level (1-5)}
    learning_rates: dict of {skill_id: months_per_level}
    """
    total_months = 0
    gaps = []

    for skill, required in role_requirements.items():
        current = candidate_skills.get(skill, 0)
        gap = max(0, required - current)
        if gap > 0:
            months = gap * learning_rates.get(skill, 6)  # default 6 mo/level
            total_months += months
            gaps.append({'skill': skill, 'gap': gap, 'months': months})

    # Account for parallel learning (30% efficiency gain)
    velocity_months = total_months * 0.7 if len(gaps) > 2 else total_months

    return {
        'estimated_months': round(velocity_months, 1),
        'skill_gaps': gaps,
        'readiness_date': pd.Timestamp.now() + pd.DateOffset(months=velocity_months)
    }

# Example usage
candidate = {'leadership': 3, 'finance': 4, 'strategy': 2}
role = {'leadership': 4, 'finance': 5, 'strategy': 4}
rates = {'leadership': 8, 'finance': 6, 'strategy': 10}

result = calculate_succession_velocity(candidate, role, rates)
print(f"Succession velocity: {result['estimated_months']} months")
print(f"Ready by: {result['readiness_date'].strftime('%Y-%m-%d')}")
